const appointment = $('Buscar Agendamento').item.json[0] || $('Buscar Agendamento').item.json;
const tenant = appointment?.tenants;
if (!appointment || !tenant) throw new Error('Agendamento ou tenant não encontrado');
if (!tenant.google_calendar_id || !tenant.google_refresh_token) return [{ json: { ok: false, error: 'Google Calendar não configurado para este tenant' } }];

const clientName = appointment.clients?.name || 'Cliente';
const serviceName = appointment.services?.name || 'Serviço';
const summary = `Agendamento ${serviceName} - ${clientName}`;
const description = `Agendamento criado via IA para ${clientName}. Serviço: ${serviceName}.`;

const body = new URLSearchParams({
  grant_type: 'refresh_token',
  refresh_token: tenant.google_refresh_token,
  client_id: process.env.GOOGLE_CLIENT_ID,
  client_secret: process.env.GOOGLE_CLIENT_SECRET,
}).toString();
const tokenRes = await fetch('https://oauth2.googleapis.com/token', {
  method: 'POST',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body,
});
const tokenData = await tokenRes.json();
if (!tokenData.access_token) throw new Error('Falha ao atualizar token do Google Calendar');

const eventRes = await fetch(`https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(tenant.google_calendar_id)}/events`, {
  method: 'POST',
  headers: {
    Authorization: `Bearer ${tokenData.access_token}`,
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({
    summary,
    description,
    start: { dateTime: appointment.starts_at },
    end: { dateTime: appointment.ends_at },
  }),
});
const eventData = await eventRes.json();
if (!eventRes.ok) throw new Error(`Google Calendar create failed: ${eventData.error?.message || JSON.stringify(eventData)}`);

const updateRes = await fetch(`${process.env.SUPABASE_URL}/rest/v1/appointments?id=eq.${appointment.id}`, {
  method: 'PATCH',
  headers: {
    apikey: process.env.SUPABASE_SERVICE_KEY,
    Authorization: `Bearer ${process.env.SUPABASE_SERVICE_KEY}`,
    'Content-Type': 'application/json',
    Prefer: 'return=representation',
  },
  body: JSON.stringify({ google_calendar_event_id: eventData.id }),
});
const updated = await updateRes.json();
return [{ json: { ok: true, event: eventData, updated: updated[0] || updated } }];
